import { difficultyTags, mineTasks, readTestSources } from './tasks.ts'
const repo = '$SP/upstream'
const tasks = (await mineTasks(repo, 120)).filter(t => !t.sourceFiles.every(f => /(^|\/)locales?(\/|\.ts$|\.tsx$)/.test(f)))
const counts: Record<string, number> = {}
for (const t of tasks) {
  const tags = difficultyTags(t, await readTestSources(repo, t))
  for (const tag of tags) counts[tag] = (counts[tag] ?? 0) + 1
  if (!tags.includes('direct')) console.log(t.id, tags.join(','), '|', t.sourceFiles.join(' '), '<-', t.testFiles.join(' '))
}
console.log(tasks.length, counts)
EOF
